package com.yuegang.zhihui.search.application;import com.yuegang.zhihui.search.infrastructure.*;import com.yuegang.zhihui.search.security.*;import java.util.*;import org.springframework.beans.factory.annotation.*;import org.springframework.context.annotation.*;import org.springframework.jdbc.core.*;
@Configuration(proxyBeanMethods=false)class SearchConfiguration{@Bean DoubaoEmbeddingGateway embeddingGateway(@Value("${ygh.search.embedding-base-url}")String b,@Value("${ygh.search.embedding-api-key}")String k,@Value("${ygh.search.embedding-model}")String m){return new DoubaoEmbeddingGateway(b,k,m);}@Bean HybridSearchService hybridSearchService(JdbcTemplate j,@Value("${ygh.search.elasticsearch-base-url}")String e,DoubaoEmbeddingGateway g,@Value("${ygh.search.index-alias:knowledge-active}")String a){return new HybridSearchService(j,e,g,a);}@Bean SearchDeletionService searchDeletionService(JdbcTemplate j,@Value("${ygh.search.elasticsearch-base-url}")String e,@Value("${ygh.search.index-alias:knowledge-active}")String a){return new SearchDeletionService(j,e,a);}@Bean IndexLifecycleService indexLifecycleService(JdbcTemplate j,@Value("${ygh.search.elasticsearch-base-url}")String e,@Value("${ygh.search.index-alias:knowledge-active}")String a){return new IndexLifecycleService(j,e,a);}@Bean SearchInternalSecurity searchInternalSecurity(@Value("${ygh.internal-request.hmac-base64}")String e){byte[]k=Base64.getDecoder().decode(e);try{return new SearchInternalSecurity(k);}finally{Arrays.fill(k,(byte)0);}}}
